const LOCKED_PHASES=new Set(['LoopPI','LoopPI2','Loop1Start','Loop1End','Loop2Start','Loop2End']);
const schema=new Map(),defaults={},fields=new Map();
for(const [name,hint,open,items] of groups){const section=document.createElement('details');section.className='param-group';section.open=open;const sum=document.createElement('summary');sum.innerHTML=name+'<svg viewBox="0 0 16 16" fill="none" aria-hidden="true"><path d="m4 6 4 4 4-4" stroke-width="1.3"/></svg>';section.append(sum);const info=document.createElement('p');info.className='group-hint';info.textContent=hint;section.append(info);for(const def of items){const [key,label,min,max,step,value]=def;schema.set(key,def);defaults[key]=typeof min==='string'?max:value;const field=document.createElement('div');let input,range;const lab=document.createElement('label');lab.textContent=label;lab.htmlFor='u-'+key;if(min==='bool'){field.className='field-check';input=document.createElement('input');input.type='checkbox';field.append(lab,input);}else if(min==='select'){field.className='field-select';input=document.createElement('select');for(const [text,v] of step){const o=document.createElement('option');o.value=v;o.textContent=text;input.append(o);}field.append(lab,input);}else{field.className='field';const row=document.createElement('div');row.className='field-row';input=document.createElement('input');input.type='number';Object.assign(input,{min,max,step});row.append(lab,input);range=document.createElement('input');range.type='range';Object.assign(range,{min,max,step});range.setAttribute('aria-label',label);field.append(row,range);}input.id='u-'+key;input.addEventListener('input',()=>{if(input.type==='number'&&(input.value===''||input.validity.badInput))return;change(key,min==='bool'?Number(input.checked):Number(input.value));});if(range)range.oninput=()=>change(key,Number(range.value));fields.set(key,{input,range});if(LOCKED_PHASES.has(key)){field.hidden=true;input.disabled=true;if(range)range.disabled=true;}section.append(field);}if(items.every(def=>LOCKED_PHASES.has(def[0])))section.hidden=true;$('parameter-groups').append(section);}


