const VIEW_STORAGE='uber-node-render-v1';let stateSaveTimer=null;
function saveView(){try{const anim=recordState&&recorder?.state==='recording'?{playing:recordState.playing,progress:recordState.progress}:{playing,progress};sessionStorage.setItem(VIEW_STORAGE,JSON.stringify({version:3,parameters:values,camera:{yaw,pitch,distance},animation:{motion,duration,easing,...anim},quality,referencePreset}));}catch(_){/* Storage unavailable: rendering and explicit JSON export remain usable. */}}
function queueViewSave(){if(stateSaveTimer!==null)return;stateSaveTimer=setTimeout(()=>{stateSaveTimer=null;saveView();},250);}
function restoreView(){try{const raw=sessionStorage.getItem(VIEW_STORAGE);if(!raw||raw.length>100000)return;const saved=JSON.parse(raw);if(![1,2,3].includes(saved.version)||!saved.parameters||!saved.camera||!saved.animation)return;const next={...reference};for(const [key,value]of Object.entries(saved.parameters)){if(!schema.has(key))continue;if(typeof value!=='number'||!Number.isFinite(value))return;const def=schema.get(key),lo=typeof def[2]==='string'?0:def[2],hi=typeof def[2]==='string'?(def[2]==='bool'?1:def[4].length-1):def[3];if(value<lo||value>hi)return;if((typeof def[2]==='string'||['Iterations','ColorIterations'].includes(key))&&!Number.isInteger(value))return;next[key]=value;}const cam=saved.camera,anim=saved.animation;if(next.MinRad>next.MaxRad||!['yaw','pitch','distance'].every(k=>Number.isFinite(cam[k]))||cam.distance<.5||cam.distance>500)return;if(!['reference','spin','loop1','loop2','both','spinloop'].includes(anim.motion)||!Number.isFinite(anim.duration)||anim.duration<1||anim.duration>60||!Number.isFinite(anim.progress)||anim.progress<0||anim.progress>1||!['linear','smooth'].includes(anim.easing)||typeof anim.playing!=='boolean'||![0,1,2,3].includes(saved.quality))return;values=next;({yaw,pitch,distance}=cam);({motion,duration,progress,easing}=anim);playing=anim.playing;quality=saved.quality;if(saved.version<3){values={...reference};yaw=0;pitch=.04;distance=8.5;duration=20;progress=0;quality=1;}for(const key of LOCKED_PHASES)values[key]=reference[key];motion='reference';easing='linear';playing=true;if(quality===3)quality=1;referencePreset=!!saved.referencePreset;$('motion').value=motion;$('duration').value=duration;$('easing').value=easing;$('uber-quality').value=quality;$('action-status').textContent=saved.version<3?'已恢复提供的参数，自动播放固定双相位动画。':'已恢复视角与参数，自动播放固定双相位动画。';}catch(_){/* Invalid saved data falls back to the supplied reference. */}}
window.addEventListener('pagehide',saveView);



