function restoreStudioOpening(){values={...reference,CameraRoll:-35};yaw=.8;pitch=.65;distance=10.5;progress=(1.695-reference.LoopPI)/(1.695-.129);playing=true;motion='reference';duration=20;easing='linear';quality=2;referencePreset=true;$('duration').value=duration;$('uber-quality').value=quality;$('action-status').textContent='已载入蓝金高光比参考画面，自动播放20秒双相位动画。';}
function sync(){for(const [key,{input,range}] of fields){if(input.type==='checkbox')input.checked=!!values[key];else input.value=values[key];if(range)range.value=values[key];}$('view-clip').value=values.ViewClip;$('clip-value').textContent=Math.round(values.ViewClip*100)+'%';drawLightBall();}
function change(key,value){if(LOCKED_PHASES.has(key))return;const def=schema.get(key);if(!Number.isFinite(value)){sync();return;}if(typeof def[2]==='string')value=def[2]==='bool'?Number(!!value):Math.max(0,Math.min(def[4].length-1,Math.round(value)));else value=Math.max(def[2],Math.min(def[3],value));if(['Iterations','ColorIterations'].includes(key))value=Math.round(value);values[key]=value;if(key==='MinRad'&&values.MinRad>values.MaxRad)values.MaxRad=values.MinRad;if(key==='MaxRad'&&values.MaxRad<values.MinRad)values.MinRad=values.MaxRad;if(key==='AbsoluteScale')distance*=Math.max(.01,fields.get(key).input.dataset.previous||.6)/value;fields.get('AbsoluteScale').input.dataset.previous=values.AbsoluteScale;if(key==='LoopPI'||key==='LoopPI2'){playing=false;motion='spin';$('motion').value=motion;progress=0;updateTransport();$('action-status').textContent='已暂停关键帧动画，现在直接调整相位。';}referencePreset=false;sync();dirty=true;}



