const canvas=$('uber-canvas'),gl=GenleWebGL.context(canvas);let program,locations={};
function error(message){$('render-error').hidden=false;$('render-error').textContent=message;$('render-status').textContent='三维渲染不可用';ready=false;for(const id of ['play','record','snapshot'])$(id).disabled=true;}
async function init(){if(!gl){error('无法启动 WebGL。请使用支持硬件加速的 Chrome 或 Edge。');return;}try{const r=await fetch('node-uber.glsl');if(!r.ok)throw Error('shader load');const code=await r.text();const device=GenleWebGL.createProgram(gl,code,[...FORMULA_UNIFORMS,...["resolution","camera","J","M","L","N","T","quality","K0","K1","K2","K3","MG","R","S"]]);program=device.program;locations=device.locations;ready=true;$('render-status').textContent='实时生成 · GIF 参数预设';requestAnimationFrame(frame);}catch(e){console.error(e);error('渲染启动失败。请刷新或更换支持 WebGL 的浏览器。');}}
function draw(){if(!ready)return;const rect=canvas.getBoundingClientRect(),factor=[.65,1,1.5,2][quality]*Math.min(devicePixelRatio,quality>=2?2:1.5);let w=Math.round(rect.width*factor),h=Math.round(rect.height*factor);if(canvas.width!==w||canvas.height!==h){canvas.width=w;canvas.height=h;}gl.viewport(0,0,w,h);gl.uniform2f(locations.resolution,w,h);motion='reference';easing='linear';for(const key of LOCKED_PHASES)values[key]=reference[key];const v=values,phase=progress*TAU/v.Power;let lp=v.LoopPI,lp2=v.LoopPI2,angle=yaw;let fraction=easing==='smooth'?progress*progress*(3-2*progress):progress;if(motion==='reference'){lp=v.Loop1Start+(v.Loop1End-v.Loop1Start)*fraction;lp2=v.Loop2Start+(v.Loop2End-v.Loop2Start)*fraction;}if(['spin','spinloop'].includes(motion))angle+=progress*TAU;if(['loop1','both','spinloop'].includes(motion))lp+=phase;if(['loop2','both'].includes(motion))lp2+=phase;gl.uniform4f(locations.camera,angle,pitch,distance*Math.max(1,rect.height/rect.width*1.12),v.CameraRoll*Math.PI/180);const uniform=(name,a)=>gl.uniform4f(locations[name],...a);uploadFormulaUniforms(uniform,v,lp,lp2);uploadRenderUniforms(uniform,v);gl.uniform1i(locations.quality,quality);gl.drawArrays(gl.TRIANGLES,0,6);dirty=false;queueViewSave();}


