function updateTransport(){queueViewSave();$('play').textContent=playing?'暂停动画':'播放动画';$('play').setAttribute('aria-pressed',String(playing));$('timeline').value=progress;let f=easing==='smooth'?progress*progress*(3-2*progress):progress;$('phase-values').textContent=motion==='reference'?'LoopPI '+(values.Loop1Start+(values.Loop1End-values.Loop1Start)*f).toFixed(4)+' · LoopPI2 '+(values.Loop2Start+(values.Loop2End-values.Loop2Start)*f).toFixed(4):'相位周期 2π / Power';$('time-value').textContent=(progress*duration).toFixed(2)+' / '+duration.toFixed(2)+' s';}


