function frame(t){if(!ready)return;const dt=last?((t-last)/1000):0;last=t;if(!document.hidden){if(playing){progress=(progress+dt/duration)%1;dirty=true;updateTransport();}if(dirty){draw();frameCount++;}if(t-fpsTime>1000){$('render-status').textContent=(referencePreset?'GIF 参数预设':'自定义参数')+' · '+(playing?frameCount+' fps':'实时三维');fpsTime=t;frameCount=0;}if(recorder&&recorder.state==='recording'&&performance.now()-recordState.started>=duration*1000)recorder.stop();}requestAnimationFrame(frame);}


