$('save-preset').onclick=()=>{const state={schema:'uber-bulb-v1',formula:'UBER BULB V3.0, Machina-Infinitum, 2020',parameters:values,animation:{motion,duration,progress,easing},camera:{yaw,pitch,distance},quality};download(new Blob([JSON.stringify(state,null,2)],{type:'application/json'}),'uber-bulb-preset.json');};$('load-preset').onclick=()=>$('preset-file').click();$('preset-file').onchange=async e=>{const file=e.target.files[0];if(!file)return;try{if(file.size>100000)throw Error('文件过大');const o=JSON.parse(await file.text());if(o.schema!=='uber-bulb-v1'||!o.parameters)throw Error('预设格式不符');for(const [key,val] of Object.entries(o.parameters)){if(!schema.has(key)||typeof val!=='number'||!Number.isFinite(val))throw Error('含有无效参数');const def=schema.get(key);const lo=typeof def[2]==='string'?0:def[2],hi=typeof def[2]==='string'?(def[2]==='bool'?1:def[4].length-1):def[3];if(val<lo||val>hi)throw Error(key+' 超出范围');if((['Iterations','ColorIterations'].includes(key)||typeof def[2]==='string')&&!Number.isInteger(val))throw Error(key+' 必须是整数');}const next={...defaults,...o.parameters};if(next.MinRad>next.MaxRad)throw Error('MinRad 不能大于 MaxRad');if(o.animation&&(!['reference','spin','loop1','loop2','both','spinloop'].includes(o.animation.motion)||!Number.isFinite(o.animation.duration)||o.animation.duration<1||o.animation.duration>60))throw Error('动画设置无效');values=next;for(const key of LOCKED_PHASES)values[key]=reference[key];referencePreset=false;playing=true;if(o.animation){motion='reference';easing='linear';$('easing').value=easing;duration=o.animation.duration;progress=Math.max(0,Math.min(1,Number(o.animation.progress)||0));$('motion').value=motion;$('duration').value=duration;}if(o.camera&&['yaw','pitch','distance'].every(k=>Number.isFinite(o.camera[k]))){yaw=o.camera.yaw;pitch=wrapAngle(o.camera.pitch);distance=Math.max(.5,Math.min(500,o.camera.distance));}quality=[0,1,2].includes(o.quality)?o.quality:1;$('uber-quality').value=quality;fields.get('AbsoluteScale').input.dataset.previous=values.AbsoluteScale;sync();dirty=true;updateTransport();$('action-status').textContent='预设已载入。';}catch(err){$('action-status').textContent='无法载入：'+err.message+'。请选择此页面导出的 JSON 预设。';}e.target.value='';};


