function zoom(f){distance=Math.max(.6/values.AbsoluteScale,Math.min(25/values.AbsoluteScale,distance*f));dirty=true;}canvas.addEventListener('wheel',e=>{e.preventDefault();zoom(Math.exp(Math.max(-150,Math.min(150,e.deltaY))*.0015));},{passive:false});const pointers=new Map();let pinch=0;canvas.onpointerdown=e=>{canvas.focus({preventScroll:true});canvas.setPointerCapture(e.pointerId);pointers.set(e.pointerId,[e.clientX,e.clientY]);if(pointers.size===2){const p=[...pointers.values()];pinch=Math.hypot(p[0][0]-p[1][0],p[0][1]-p[1][1]);}};canvas.onpointermove=e=>{if(!pointers.has(e.pointerId))return;const old=pointers.get(e.pointerId);pointers.set(e.pointerId,[e.clientX,e.clientY]);if(pointers.size===2){const p=[...pointers.values()],d=Math.hypot(p[0][0]-p[1][0],p[0][1]-p[1][1]);if(pinch>0&&d>0)zoom(pinch/d);pinch=d;}else{yaw-=(e.clientX-old[0])*.007;pitch=wrapAngle(pitch+(e.clientY-old[1])*.007);dirty=true;}};for(const name of ['pointerup','pointercancel','lostpointercapture'])canvas.addEventListener(name,e=>{pointers.delete(e.pointerId);pinch=0;});canvas.onkeydown=e=>{if(e.key.startsWith('Arrow')){e.preventDefault();if(e.key==='ArrowLeft')yaw-=.1;if(e.key==='ArrowRight')yaw+=.1;if(e.key==='ArrowUp')pitch=wrapAngle(pitch+.1);if(e.key==='ArrowDown')pitch=wrapAngle(pitch-.1);dirty=true;}if(e.key==='+'||e.key==='='){e.preventDefault();zoom(.9);}if(e.key==='-'){e.preventDefault();zoom(1.1);}};


